-- =====================================================================
--  transit.db  -  city transit cards (mock data, generated by src/gen_transit.py)
--  amount_kurus: boarding < 0, topup > 0, refund > 0  (same rule as the course)
--  cards.balance_kurus is consistent with SUM(swipes.amount_kurus) at reset.
--  NO triggers are installed - building them is your job (section 10).
-- =====================================================================
PRAGMA foreign_keys = ON;

CREATE TABLE fares (
    card_type   TEXT PRIMARY KEY,
    fare_kurus  INTEGER NOT NULL CHECK (fare_kurus > 0)
);

CREATE TABLE cards (
    id            INTEGER PRIMARY KEY,
    owner         TEXT NOT NULL,
    card_type     TEXT NOT NULL REFERENCES fares(card_type),
    issued_at     TEXT NOT NULL,
    balance_kurus INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE stations (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL UNIQUE,
    district TEXT NOT NULL,
    line     TEXT NOT NULL CHECK (line IN ('Tram', 'Bus')),
    closed   INTEGER NOT NULL DEFAULT 0 CHECK (closed IN (0, 1))
);

CREATE TABLE swipes (
    id           INTEGER PRIMARY KEY,
    card_id      INTEGER NOT NULL REFERENCES cards(id),
    station_id   INTEGER REFERENCES stations(id),
    type         TEXT NOT NULL CHECK (type IN ('boarding', 'refund', 'topup')),
    datetime     TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    amount_kurus INTEGER NOT NULL CHECK (typeof(amount_kurus) = 'integer'),
    CHECK (
        (type = 'boarding' AND amount_kurus < 0) OR
        (type = 'refund'   AND amount_kurus > 0) OR
        (type = 'topup'    AND amount_kurus > 0)
    )
);










